// Des: Car field normalizers: price, km, year, gearbox, phone digits
// Flo: Vietnamese listing text > integer or short code; unknown gives 0 (price, year), -1 (km) or empty
// I/O: text in > number or static code out; no allocation, no clock, never a crash on odd bytes
// ===================================================================
const std = @import("std");
pub fn hasz(hayz: []const u8, nedl: []const u8) bool { if (nedl.len == 0) return true; if (hayz.len < nedl.len) return false; var posi: usize = 0; while (posi + nedl.len <= hayz.len) : (posi += 1) { if (std.ascii.eqlIgnoreCase(hayz[posi .. posi + nedl.len], nedl)) return true; } return false; }
fn wordWhol(hayz: []const u8, nedl: []const u8) bool { var posi: usize = 0; while (posi + nedl.len <= hayz.len) : (posi += 1) { if (!std.ascii.eqlIgnoreCase(hayz[posi .. posi + nedl.len], nedl)) continue; const befo = posi == 0 or !std.ascii.isAlphabetic(hayz[posi - 1]); const afte = posi + nedl.len == hayz.len or !std.ascii.isAlphabetic(hayz[posi + nedl.len]); if (befo and afte) return true; } return false; }
fn starPref(rest: []const u8, patn: []const u8) bool { return rest.len >= patn.len and std.ascii.eqlIgnoreCase(rest[0..patn.len], patn); }
const Unit = struct { kind: u8, next: usize };
fn unitFind(text: []const u8, from: usize) Unit { var posi = from; while (posi < text.len and text[posi] == ' ') posi += 1; const rest = text[posi..]; if (starPref(rest, "tỷ")) return .{ .kind = 1, .next = posi + 4 }; if (starPref(rest, "tỉ")) return .{ .kind = 1, .next = posi + 4 }; if (starPref(rest, "ty") and !(rest.len > 2 and std.ascii.isAlphabetic(rest[2]))) return .{ .kind = 1, .next = posi + 2 }; if (starPref(rest, "triệu")) return .{ .kind = 2, .next = posi + 7 }; if (starPref(rest, "trieu")) return .{ .kind = 2, .next = posi + 5 }; if (starPref(rest, "tr") and !(rest.len > 2 and std.ascii.isAlphabetic(rest[2]))) return .{ .kind = 2, .next = posi + 2 }; return .{ .kind = 0, .next = from }; }
fn scalNumz(numz: []const u8, unit: i64, kind: u8) i64 { var dots: usize = 0; var coms: usize = 0; for (numz) |byte| { if (byte == '.') dots += 1; if (byte == ',') coms += 1; } var cutz: ?usize = null; if (dots + coms == 1 and kind != 0) { const sepz = std.mem.indexOfAny(u8, numz, ".,").?; const afte = numz.len - sepz - 1; if (kind == 1 or afte != 3) cutz = sepz; } else if (dots >= 1 and coms >= 1) { cutz = std.mem.lastIndexOfAny(u8, numz, ".,"); } var whol: i64 = 0; var frac: i64 = 0; var fdig: i64 = 0; for (numz, 0..) |byte, indx| { if (!std.ascii.isDigit(byte)) continue; if (cutz != null and indx > cutz.?) { if (fdig < 6) { frac = frac * 10 + (byte - '0'); fdig += 1; } } else { whol = whol * 10 + (byte - '0'); if (whol > 1_000_000_000_000) return 0; } } var scal: i64 = 1; var iter: i64 = 0; while (iter < fdig) : (iter += 1) scal *= 10; return whol * unit + @divTrunc(frac * unit, scal); }
pub fn normPric(tex0: []const u8) i64 { const cut0 = std.mem.indexOfScalar(u8, tex0, '(') orelse tex0.len; const text = tex0[0..cut0]; var totl: i64 = 0; var sawu = false; var posi: usize = 0; while (posi < text.len) { if (!std.ascii.isDigit(text[posi])) { posi += 1; continue; } var endz = posi; while (endz < text.len and (std.ascii.isDigit(text[endz]) or ((text[endz] == '.' or text[endz] == ',') and endz + 1 < text.len and std.ascii.isDigit(text[endz + 1])))) endz += 1; const numz = text[posi..endz]; const unit = unitFind(text, endz); if (unit.kind != 0) { sawu = true; totl += scalNumz(numz, if (unit.kind == 1) 1_000_000_000 else 1_000_000, unit.kind); posi = unit.next; } else { if (!sawu and totl == 0) { const flat = scalNumz(numz, 1, 0); if (flat >= 1_000_000) return flat; } posi = endz; } } return if (totl >= 1_000_000) totl else 0; }
pub fn normKmzz(text: []const u8) i64 { var posi: usize = 0; while (posi < text.len and !std.ascii.isDigit(text[posi])) posi += 1; if (posi == text.len) return -1; var endz = posi; while (endz < text.len and (std.ascii.isDigit(text[endz]) or ((text[endz] == '.' or text[endz] == ',') and endz + 1 < text.len and std.ascii.isDigit(text[endz + 1])))) endz += 1; var rest = endz; while (rest < text.len and text[rest] == ' ') rest += 1; const numz = text[posi..endz]; if (starPref(text[rest..], "vạn")) return scalNumz(numz, 10000, 1); return scalNumz(numz, 1, 0); }
pub fn normYear(text: []const u8) i64 { var posi: usize = 0; while (posi + 4 <= text.len) : (posi += 1) { if (posi > 0 and std.ascii.isDigit(text[posi - 1])) continue; const slic = text[posi .. posi + 4]; var okay = true; for (slic) |byte| { if (!std.ascii.isDigit(byte)) okay = false; } if (!okay) continue; if (posi + 4 < text.len and std.ascii.isDigit(text[posi + 4])) continue; const valu = std.fmt.parseInt(i64, slic, 10) catch continue; if (valu >= 1950 and valu <= 2100) return valu; } return 0; }
pub fn normGear(text: []const u8) []const u8 { if (hasz(text, "cvt")) return "CVT"; if (hasz(text, "dct") or hasz(text, "ly hợp kép")) return "DCT"; if (hasz(text, "tự động") or wordWhol(text, "at") or hasz(text, "automatic")) return "AT"; if (hasz(text, "sàn") or hasz(text, "số tay") or wordWhol(text, "mt") or hasz(text, "manual")) return "MT"; return ""; }
pub fn normPowr(text: []const u8) []const u8 { if (hasz(text, "plug-in") or hasz(text, "plugin") or wordWhol(text, "phev") or hasz(text, "sạc ngoài")) return "PHEV"; if (hasz(text, "mild") or wordWhol(text, "mhev")) return "MHEV"; if (hasz(text, "hybrid") or wordWhol(text, "hev")) return "HEV"; if (hasz(text, "hydrogen") or hasz(text, "hidro")) return "H2"; if (hasz(text, "điện") or hasz(text, "Điện") or hasz(text, "electric") or wordWhol(text, "bev") or wordWhol(text, "ev")) return "BEV"; if (hasz(text, "lpg") or hasz(text, "cng")) return "LPG"; if (hasz(text, "dầu") or hasz(text, "diesel")) return "DSL"; if (hasz(text, "xăng") or hasz(text, "gasoline") or hasz(text, "petrol")) return "GAS"; return ""; }
pub fn normCond(text: []const u8) []const u8 { if (hasz(text, "demo") or hasz(text, "lái thử")) return "demo"; if (hasz(text, "đã sử dụng") or hasz(text, "Đã sử dụng") or hasz(text, "xe cũ") or hasz(text, "đã qua") or wordWhol(text, "cũ")) return "used"; if (hasz(text, "mới")) return "new"; return ""; }
pub const Phon = struct { digi: []const u8, full: bool };
pub fn normPhon(text: []const u8, buff: *[16]u8) Phon { var lenz: usize = 0; var mask = false; for (text) |byte| { if (std.ascii.isDigit(byte)) { if (lenz < buff.len) { buff[lenz] = byte; lenz += 1; } } else if (byte == '*' or byte == 'x' or byte == 'X') mask = true; } return .{ .digi = buff[0..lenz], .full = !mask and lenz >= 9 and lenz <= 11 }; }
